"""PL-02 step 2: returns from prices."""

from __future__ import annotations

import math
from itertools import pairwise

from mdata.types import Prices
from risk.types import Returns


def log_returns(prices: Prices) -> Returns:
    """Each ticker's log return ln(close_t / close_t-1), dated t."""
    if len(prices.dates) < 2:
        raise ValueError("returns need at least two dates")
    values = {
        ticker: tuple(math.log(now / before) for before, now in pairwise(closes))
        for ticker, closes in prices.closes.items()
    }
    return Returns(
        base_date=prices.dates[0], dates=prices.dates[1:], tickers=prices.tickers, values=values
    )

